"use strict";(globalThis.webpackChunksap_architecture_center=globalThis.webpackChunksap_architecture_center||[]).push([[40832],{89041(e){e.exports=JSON.parse('{"tag":{"label":"AI-native North Star architecture","permalink":"/architecture-center/docs/tags/ai-native-north-star","description":"The AI-native North Star architecture defines the target state of SAP\'s technology landscape. It is not a specification, roadmap, or promise of delivery. It is a direction of travel; a statement of how AI, data, processes, and the platform must work together as intelligence becomes the norm rather than an add-on.","allTagsPath":"/architecture-center/docs/tags","count":20,"items":[{"id":"north-star-arch/ai-native-northstar-arch/acknowledgement/id-nsa-13","title":"Acknowledgements for the North Star Architecture","description":"Acknowledgement of the core contributors from SAP who shaped the AI-native North Star architecture, listed alphabetically by last name.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/acknowledgement"},{"id":"north-star-arch/ai-native-northstar-arch/executive-summary/id-nsa-1","title":"AI-Native Architecture: Executive Summary","description":"Enterprise AI shifts from AI-first to AI-native: SAP\'s system of context lets agents reason across the enterprise and moves value to Outcome as a Service.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/executive-summary"},{"id":"north-star-arch/ai-native-northstar-arch/customer-specific-development-services/id-nsa-10","title":"AI-Native Customer-Specific Development Services","description":"SAP\'s AI-native customer-specific development services deliver upgrade-safe extensions that learn and adapt in production via agentic engineering.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/customer-specific-development-services"},{"id":"north-star-arch/ai-native-northstar-arch/ai-native-nsa-vision/id-nsa-2","title":"AI-native North Star architecture - Vision","description":"The vision for SAP\'s AI-native North Star architecture: four layers - User Experience, Process, Foundation, and Platform - forming a system of context.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/vision"},{"id":"north-star-arch/ai-native-northstar-arch/user-experience-layer/id-nsa-3","title":"AI-native User Experience Layer with Joule Work","description":"The AI-native User Experience Layer shifts users from navigating apps to stating intent, as Joule Work unifies generative, voice, and multimodal experiences.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/user-experience-layer"},{"id":"north-star-arch/ai-native-northstar-arch/foreword/id-nsa-foreword-2","title":"Anirban Majumdar on the AI-native North Star architecture","description":"The AI-native North Star architecture is SAP\'s blueprint for the Autonomous Enterprise, in a foreword by Anirban Majumdar, Head of SAP\'s Office of the CTO.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/foreword/anirban-majumdar"},{"id":"north-star-arch/ai-native-northstar-arch/architecting-for-the-quantum-era/id-nsa-11","title":"Architecting for the quantum era","description":"How SAP\'s AI-native North Star architecture prepares for the quantum era with QPU coprocessors, cloud-native APIs, and scoped analytical use.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/architecting-for-the-quantum-era"},{"id":"north-star-arch/ai-native-northstar-arch/closing-note/id-nsa-12","title":"Closing Note","description":"Closing note on the AI-native enterprise as a cybernetic system, where architects shift to agentic engineering built on SAP\'s integration and trust.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/closing-note"},{"id":"north-star-arch/ai-native-northstar-arch/ecosystem/id-nsa-8","title":"Ecosystem: The marketplace for agents, tools, and extensions","description":"Trust makes collaboration possible: a marketplace where agents, data products, and tools are registered, versioned, shared, and composed into solutions across organizational boundaries.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/ecosystem"},{"id":"north-star-arch/ai-native-northstar-arch/foundation-layer/id-nsa-5","title":"Foundation Layer: AI, Data & Knowledge Graph","description":"The AI-native foundation layer makes data and AI the intelligent core, grounded by SAP Business Data Cloud and SAP Knowledge Graph for governed context.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/foundation-layer"},{"id":"north-star-arch/ai-native-northstar-arch/foreword/id-nsa-foreword-5","title":"Geoff Scott on the AI-native North Star architecture","description":"ASUG CEO Geoff Scott on SAP\'s AI-native North Star architecture: customers need clarity amid fast-moving enterprise AI, and ASUG commends SAP\'s rigor.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/foreword/geoff-scott"},{"id":"north-star-arch/ai-native-northstar-arch/integration-security-ethics-governance/id-nsa-7","title":"Integration, Security, Ethics & Governance","description":"How SAP\'s AI-native architecture governs agents: a governed gateway, scoped agent identity, three-tier AI defense, and AI ethics review under the EU AI Act.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/integration-security-ethics-governance"},{"id":"north-star-arch/ai-native-northstar-arch/key-terms/id-nsa-14","title":"Key Terms - AI-native North Star Architecture","description":"Glossary of key terms and definitions used across SAP\'s AI-native North Star architecture, from system of context to agentic orchestration and sovereign AI.","permalink":"/architecture-center/docs/north-star-arch/ai-native-northstar-arch/key-terms/"},{"id":"north-star-arch/ai-native-northstar-arch/foreword/id-nsa-foreword-1","title":"Philipp Herzig on the AI-native North Star architecture","description":"SAP CTO Philipp Herzig on the AI-native North Star architecture: moving from AI-first to AI-native toward one system of context for the Autonomous Enterprise.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/foreword/philipp-herzig"},{"id":"north-star-arch/ai-native-northstar-arch/platform-layer/id-nsa-6","title":"Platform Layer: Managed Agent Runtime at Scale","description":"The AI-native platform layer runs apps, agents, and workflows at enterprise scale on a managed agent runtime, with sovereign AI and governance built in.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/platform-layer"},{"id":"north-star-arch/ai-native-northstar-arch/process-layer/id-nsa-4","title":"Process Layer: Agentic Orchestration & Joule Studio","description":"The AI-native process layer shifts business logic to agent-driven orchestration, with apps as capability providers and Joule Studio for agentic solutions.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/process-layer"},{"id":"north-star-arch/ai-native-northstar-arch/id-nsa-0","title":"SAP AI-native North Star Reference Architecture","description":"SAP\'s AI-native North Star architecture defines the target state of SAP\'s technology landscape: a strategic direction, not a specification or product roadmap.","permalink":"/architecture-center/docs/ai-native-north-star-architecture"},{"id":"north-star-arch/ai-native-northstar-arch/foreword/id-nsa-foreword-3","title":"Stefan Nogly on the AI-native North Star architecture","description":"DSAG\'s perspective on SAP\'s AI-native North Star architecture: a strategic roadmap for AI transformation and a shared responsibility to develop solutions.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/foreword/stefan-nogly"},{"id":"north-star-arch/ai-native-northstar-arch/resilient-and-sovereign-cloud/id-nsa-9","title":"The Resilient and Sovereign Cloud for AI Workloads","description":"SAP\'s resilient and sovereign cloud delivers AI-native workloads across public, private, sovereign, and on-site models with data sovereignty and compliance.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/resilient-and-sovereign-cloud"},{"id":"north-star-arch/ai-native-northstar-arch/foreword/id-nsa-foreword-4","title":"Thomas Henzler on AI governance in SAP\'s North Star","description":"DSAG\'s Thomas Henzler on governance in SAP\'s AI-native North Star architecture, a strategic framework for AI transformation across the enterprise.","permalink":"/architecture-center/docs/ai-native-north-star-architecture/foreword/thomas-henzler"}],"unlisted":false}}')}}]);